// The mind map drawn by markmap.
//
// The one that reads like an outline rather than a diagram: no boxes, just the
// words with a curve leading to each, spreading rightwards. It is the most
// legible of the four for a deep tree, and the least like a drawing - which is
// why it is worth having beside the other three rather than instead of them.
//
// markmap normally starts from markdown. It is handed the tree directly here
// instead: writing the outline out as markdown and parsing it back would lose
// the heading hash and mean escaping every character markdown reads, and its
// renderer takes a tree perfectly well.

import * as React from 'react';
import Box from '@mui/joy/Box';

import { Markmap } from 'markmap-view';

import { MindLook, MindNode, toMarkmap } from '../mindmap';

export interface MarkMapHandle {
    svg: () => string;
    fit: () => void;
    zoom: (by: number) => void;
}

interface Props {
    root: MindNode;
    look: MindLook;
    colorFor: (n: MindNode) => string;
    show: { status: boolean; priority: boolean; tags: boolean };
    openTo: number;
    spacing: { horizontal: number; vertical: number };
    onPick?: (id: string) => void;
}

const MarkMap = React.forwardRef<MarkMapHandle, Props>(function MarkMap(props, ref) {
    const svgRef = React.useRef<SVGSVGElement>(null);
    const mmRef = React.useRef<Markmap | null>(null);

    const { root, look, colorFor, openTo, spacing } = props;
    const { status, priority, tags } = props.show;
    const pickRef = React.useRef(props.onPick);
    pickRef.current = props.onPick;

    React.useEffect(() => {
        const el = svgRef.current;
        if (!el) return;

        const data = toMarkmap(root, { status, priority, tags, colorFor, openTo });

        const mm = Markmap.create(el, {
            // The colour is carried on the node rather than worked out from an
            // index, so that the palette and the colour-by control mean the
            // same thing here as everywhere else.
            color: (n: any) => (n && n.payload && n.payload.color) || look.accent,
            duration: 250,
            spacingHorizontal: spacing.horizontal,
            spacingVertical: spacing.vertical,
            paddingX: 12,
            autoFit: true,
            fitRatio: 0.92,
            // Folding is on the nodes already (payload.fold), so this is left
            // wide: a level given here would fight the depth control.
            initialExpandLevel: -1,
            zoom: true,
            pan: true,
        }, data as any);
        mmRef.current = mm;

        // markmap draws the label as html inside a foreignObject, so a click
        // lands on whatever piece of the label was under the pointer; the id
        // is found by walking back up to the node group.
        const onClick = (ev: MouseEvent) => {
            const g = (ev.target as Element | null)?.closest?.('g.markmap-node');
            if (!g) return;
            const datum = (g as any).__data__;
            const id = datum && datum.payload && datum.payload.id;
            if (id && pickRef.current) pickRef.current(String(id));
        };
        el.addEventListener('click', onClick);

        // markmap moves its nodes into place with a d3 transition, and d3
        // transitions run on requestAnimationFrame - which a hidden tab does
        // not fire. A map drawn while the tab was in the background therefore
        // stays stacked at the origin until something redraws it, so it is
        // drawn again when the tab comes back. The layout itself was right all
        // along; only the animation that applies it was asleep.
        const onVisible = () => {
            if (document.hidden) return;
            const live = mmRef.current;
            if (!live) return;
            live.renderData();
            live.fit();
        };
        document.addEventListener('visibilitychange', onVisible);

        return () => {
            el.removeEventListener('click', onClick);
            document.removeEventListener('visibilitychange', onVisible);
            mmRef.current = null;
            try { mm.destroy(); } catch { /* already gone with the element */ }
        };
    }, [root, look, colorFor, status, priority, tags, openTo, spacing]);

    React.useImperativeHandle(ref, () => ({
        svg: () => (svgRef.current ? svgRef.current.outerHTML : ''),
        fit: () => { const mm = mmRef.current; if (mm) mm.fit(); },
        zoom: (by: number) => {
            const mm = mmRef.current;
            const el = svgRef.current;
            if (!mm || !el) return;
            // markmap zooms through d3; scaleBy is the supported way in.
            const z: any = (mm as any).zoom;
            const d3sel: any = (mm as any).svg;
            if (z && d3sel && typeof z.scaleBy === 'function') {
                z.scaleBy(d3sel.transition().duration(200), by > 0 ? 1.25 : 0.8);
            }
        },
    }), []);

    return (
        <Box sx={{
            width: '100%', height: '100%', minHeight: 0,
            '& svg.orgs-markmap': { width: '100%', height: '100%', display: 'block' },
            // markmap draws its labels as html, so the page's own ink is what
            // they inherit - which is also what makes it follow light and dark.
            '& .markmap-foreign': { color: look.text, fontSize: '14px' },
            '& .mm-kw': { fontWeight: 700, opacity: 0.85 },
            '& .mm-pri': { fontStyle: 'normal', opacity: 0.7, fontSize: '0.85em' },
            '& .mm-tags': { opacity: 0.55, fontSize: '0.8em' },
        }}>
            <svg ref={svgRef} className="orgs-markmap" />
        </Box>
    );
});

export default MarkMap;
